-- Private backend schema; never add it to Data API exposed schemas.
CREATE SCHEMA IF NOT EXISTS your_car;
REVOKE ALL ON SCHEMA your_car FROM PUBLIC,anon,authenticated;
CREATE TABLE your_car.users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"name" TEXT,"email" TEXT,"role" TEXT,"active" BIGINT CHECK("active" IN (0,1)),password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.vehicles(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"brand" TEXT,"model" TEXT,"version" TEXT,"year" BIGINT,"km" BIGINT,"condition" TEXT,"transmission" TEXT,"fuel" TEXT,"color" TEXT,"body" TEXT,"location" TEXT,"price" BIGINT,"cost" BIGINT,"status" TEXT,"image" TEXT,"gallery" TEXT,"description" TEXT,"features" TEXT,"offer" BIGINT CHECK("offer" IN (0,1)),created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.customers(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"name" TEXT,"email" TEXT,"phone" TEXT,"notes" TEXT,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.leads(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"name" TEXT,"email" TEXT,"phone" TEXT,"vehicle_id" INTEGER REFERENCES your_car.vehicles(id),"seller_id" INTEGER REFERENCES your_car.users(id),"source" TEXT,"status" TEXT,"message" TEXT,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.orders(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"customer_id" INTEGER REFERENCES your_car.customers(id),"vehicle_id" INTEGER REFERENCES your_car.vehicles(id),"seller_id" INTEGER REFERENCES your_car.users(id),"status" TEXT,"notes" TEXT,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.expenses(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"description" TEXT,"amount" BIGINT,"category" TEXT,"date" TEXT,"vehicle_id" INTEGER REFERENCES your_car.vehicles(id),created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.appointments(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"name" TEXT,"phone" TEXT,"email" TEXT,"vehicle_id" INTEGER REFERENCES your_car.vehicles(id),"seller_id" INTEGER REFERENCES your_car.users(id),"date" TEXT,"time" TEXT,"status" TEXT,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.settings(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"name" TEXT,"value" TEXT,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.notifications(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"title" TEXT,"message" TEXT,"read" BIGINT CHECK("read" IN (0,1)),created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE UNIQUE INDEX users_email ON your_car.users(email);
CREATE UNIQUE INDEX settings_name ON your_car.settings(name);
CREATE TABLE your_car.sales(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,vehicle_id INTEGER NOT NULL UNIQUE REFERENCES your_car.vehicles(id),customer_id INTEGER NOT NULL REFERENCES your_car.customers(id),seller_id INTEGER NOT NULL REFERENCES your_car.users(id),lead_id INTEGER REFERENCES your_car.leads(id),order_id INTEGER REFERENCES your_car.orders(id),amount BIGINT NOT NULL CHECK(amount>0),cost BIGINT NOT NULL,profit BIGINT NOT NULL,margin DOUBLE PRECISION NOT NULL,date TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.payments(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sale_id INTEGER NOT NULL REFERENCES your_car.sales(id),amount BIGINT NOT NULL CHECK(amount>0),date TEXT NOT NULL,method TEXT NOT NULL);
CREATE TABLE your_car.audit(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES your_car.users(id),action TEXT NOT NULL,entity TEXT NOT NULL,record_id INTEGER,detail TEXT,created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.public_requests(reference TEXT PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES your_car.orders(id));
CREATE TABLE your_car.rate_limits(key TEXT PRIMARY KEY,window_start BIGINT NOT NULL,count BIGINT NOT NULL);
CREATE TABLE your_car.media_uploads(pathname TEXT PRIMARY KEY,user_id INTEGER REFERENCES your_car.users(id),url TEXT UNIQUE,state TEXT NOT NULL CHECK(state IN ('PENDING','ACTIVE','DELETING','DELETED','FAILED')),created_at TEXT DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE your_car.order_tracking(order_id INTEGER PRIMARY KEY REFERENCES your_car.orders(id),order_number TEXT NOT NULL UNIQUE DEFAULT ('#P'||substr(replace(gen_random_uuid()::text,'-',''),1,12)),stage TEXT NOT NULL DEFAULT 'RECEBIDO' CHECK(stage IN ('RECEBIDO','CONFIRMADO','EM_PREPARO','PRONTO')));
CREATE FUNCTION your_car.track_new_order() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN INSERT INTO your_car.order_tracking(order_id) VALUES(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER track_new_order AFTER INSERT ON your_car.orders FOR EACH ROW EXECUTE FUNCTION your_car.track_new_order();
REVOKE ALL ON FUNCTION your_car.track_new_order() FROM PUBLIC,anon,authenticated;
CREATE UNIQUE INDEX one_reservation_per_vehicle ON your_car.orders(vehicle_id) WHERE status='RESERVADO';
CREATE INDEX sales_date ON your_car.sales(date);
CREATE INDEX payments_date ON your_car.payments(date);
CREATE INDEX payments_sale ON your_car.payments(sale_id);
CREATE INDEX orders_vehicle ON your_car.orders(vehicle_id);
CREATE INDEX orders_customer ON your_car.orders(customer_id);
CREATE INDEX expenses_vehicle ON your_car.expenses(vehicle_id);
CREATE INDEX expenses_date ON your_car.expenses(date);
CREATE INDEX leads_vehicle ON your_car.leads(vehicle_id);
CREATE INDEX audit_user ON your_car.audit(user_id);
ALTER TABLE your_car.users ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON your_car.users FROM PUBLIC,anon,authenticated;
ALTER TABLE your_car.vehicles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON your_car.vehicles FROM PUBLIC,anon,authenticated;
