REVOKE ALL ON your_car.sales FROM PUBLIC,anon,authenticated;
ALTER TABLE your_car.payments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON your_car.payments FROM PUBLIC,anon,authenticated;
ALTER TABLE your_car.audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON your_car.audit FROM PUBLIC,anon,authenticated;
ALTER TABLE your_car.public_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON your_car.public_requests FROM PUBLIC,anon,authenticated;
ALTER TABLE your_car.rate_limits ENABLE ROW LEVEL SECURITY;
