ALTER TABLE your_car.media_uploads ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON your_car.media_uploads FROM PUBLIC,anon,authenticated;
ALTER TABLE your_car.order_tracking ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON your_car.order_tracking FROM PUBLIC,anon,authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA your_car FROM PUBLIC,anon,authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA your_car REVOKE ALL ON TABLES FROM PUBLIC,anon,authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA your_car REVOKE ALL ON SEQUENCES FROM PUBLIC,anon,authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA your_car REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC,anon,authenticated;

ALTER TABLE your_car.users ADD CONSTRAINT valid_role CHECK(role IN ('ADMIN','VENDEDOR'));
ALTER TABLE your_car.vehicles ADD CONSTRAINT valid_vehicle_status CHECK(status IN ('DISPONIVEL','RESERVADO','VENDIDO'));
ALTER TABLE your_car.vehicles ADD CONSTRAINT valid_vehicle_values CHECK(price>0 AND cost>=0 AND km>=0);
ALTER TABLE your_car.vehicles ADD CONSTRAINT valid_condition CHECK(condition IN ('Usado','Seminovo','Novo','0 km'));
ALTER TABLE your_car.orders ADD CONSTRAINT valid_order_status CHECK(status IN ('PENDENTE','RESERVADO','CANCELADO','CONCLUIDO'));
ALTER TABLE your_car.leads ADD CONSTRAINT valid_lead_status CHECK(status IN ('NOVO','CONTATO','NEGOCIACAO','CONVERTIDO','PERDIDO'));
ALTER TABLE your_car.expenses ADD CONSTRAINT positive_expense CHECK(amount>0);
CREATE INDEX appointments_vehicle ON your_car.appointments(vehicle_id);
CREATE INDEX appointments_seller ON your_car.appointments(seller_id);
CREATE INDEX leads_seller ON your_car.leads(seller_id);
CREATE INDEX orders_seller ON your_car.orders(seller_id);
CREATE INDEX sales_customer ON your_car.sales(customer_id);
CREATE INDEX sales_seller ON your_car.sales(seller_id);
CREATE INDEX sales_lead ON your_car.sales(lead_id);
CREATE INDEX sales_order ON your_car.sales(order_id);
CREATE INDEX public_requests_order ON your_car.public_requests(order_id);
CREATE INDEX media_uploads_user ON your_car.media_uploads(user_id);
